import React, { useState, useEffect } from 'react';
import {
    Box,
    Card,
    CardContent,
    Typography,
    Button,
    Select,
    MenuItem,
    FormControl,
    InputLabel,
    Grid,
    Chip,
    Alert,
    CircularProgress,
    Accordion,
    AccordionSummary,
    AccordionDetails,
    Table,
    TableBody,
    TableCell,
    TableContainer,
    TableHead,
    TableRow,
    Paper,
    Checkbox,
    FormControlLabel,
    FormGroup,
    Divider
} from '@mui/material';
import {
    ExpandMore,
    Store,
    ViewModule,
    PlayArrow,
    Info
} from '@mui/icons-material';

import { apiService } from '../services/api';
import { socketService } from '../services/socket';
import ProgressTracker from './ProgressTracker';
import ResultsViewer from './ResultsViewer';

interface StoreTemplate {
    store_name: string;
    location: string;
    city: string;
    cm: string;
    walls: WallInfo[];
    total_walls: number;
}

interface WallInfo {
    wall_id: string;
    panel_name: string;
    brand: string;
    brand_type: string;
    product: string;
    product_type: string;
    total_facings: number;
    shelf_info: {
        shelf_count: number;
        per_shelf: number;
        shelf_capacity: number;
    };
    peg_info: {
        peg_count: number;
        per_peg: number;
        peg_capacity: number;
    };
}

interface StoreWalls {
    store_name: string;
    lob_groups: {
        [key: string]: WallInfo[];
    };
    summary: {
        [key: string]: {
            wall_count: number;
            total_facings: number;
        };
    };
    total_facings: number;
    total_walls: number;
}

const StoreOptimization: React.FC = () => {
    const [stores, setStores] = useState<StoreTemplate[]>([]);
    const [selectedStore, setSelectedStore] = useState<string>('');
    const [storeWalls, setStoreWalls] = useState<StoreWalls | null>(null);
    const [selectedLobs, setSelectedLobs] = useState<string[]>(['Apple Panel', 'TPA Panel', 'Mixed Panel']);
    const [loading, setLoading] = useState(false);
    const [error, setError] = useState<string | null>(null);

    // Progress tracking state
    const [progressOpen, setProgressOpen] = useState(false);
    const [currentJobId, setCurrentJobId] = useState<string | null>(null);

    // Results viewer state
    const [resultsOpen, setResultsOpen] = useState(false);
    const [completedJobId, setCompletedJobId] = useState<string | null>(null);

    useEffect(() => {
        loadStoreTemplates();
    }, []);

    const loadStoreTemplates = async () => {
        setLoading(true);
        setError(null);

        try {
            const response = await apiService.getStoreTemplates();
            if (response.success && response.data) {
                setStores(response.data.stores);
            } else {
                setError(response.error?.message || 'Failed to load store templates');
            }
        } catch (err: any) {
            setError('Unable to connect to backend server');
            console.error('Store templates error:', err);
        } finally {
            setLoading(false);
        }
    };

    const loadStoreWalls = async (storeName: string) => {
        setLoading(true);
        setError(null);

        try {
            const response = await apiService.getStoreWalls(storeName);
            if (response.success && response.data) {
                setStoreWalls(response.data);
            } else {
                setError(response.error?.message || 'Failed to load store walls');
            }
        } catch (err: any) {
            setError('Unable to load store walls');
            console.error('Store walls error:', err);
        } finally {
            setLoading(false);
        }
    };

    const handleStoreChange = (storeName: string) => {
        setSelectedStore(storeName);
        setStoreWalls(null);
        if (storeName) {
            loadStoreWalls(storeName);
        }
    };

    const handleLobToggle = (lob: string) => {
        setSelectedLobs(prev => 
            prev.includes(lob) 
                ? prev.filter(l => l !== lob)
                : [...prev, lob]
        );
    };

    const startOptimization = async () => {
        if (!selectedStore || selectedLobs.length === 0) {
            setError('Please select a store and at least one LOB');
            return;
        }

        try {
            const response = await apiService.startStoreOptimization(selectedStore, {
                optimization_type: 'full_store',
                selected_lobs: selectedLobs,
                additional_params: {}
            });

            if (response.success && response.data) {
                setCurrentJobId(response.data.job_id);
                setProgressOpen(true);
                setError(null);
            } else {
                setError(response.error?.message || 'Failed to start optimization');
            }
        } catch (err: any) {
            setError('Unable to start optimization');
            console.error('Optimization error:', err);
        }
    };

    const handleProgressClose = () => {
        setProgressOpen(false);
        setCurrentJobId(null);
    };

    const handleJobComplete = (result: any) => {
        setProgressOpen(false);
        setCompletedJobId(currentJobId);
        setResultsOpen(true);
    };

    const handleResultsClose = () => {
        setResultsOpen(false);
        setCompletedJobId(null);
    };

    const getLobColor = (lob: string) => {
        switch (lob) {
            case 'Apple Panel': return 'primary';
            case 'TPA Panel': return 'secondary';
            case 'Mixed Panel': return 'success';
            default: return 'default';
        }
    };

    return (
        <Box sx={{ p: 3 }}>
            <Typography variant="h4" gutterBottom sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                <Store />
                Store-Based Planogram Optimization
            </Typography>

            {error && (
                <Alert severity="error" sx={{ mb: 2 }}>
                    {error}
                </Alert>
            )}

            <Grid container spacing={3}>
                {/* Store Selection */}
                <Grid item xs={12} md={6}>
                    <Card>
                        <CardContent>
                            <Typography variant="h6" gutterBottom>
                                Select Store
                            </Typography>

                            <FormControl fullWidth sx={{ mb: 2 }}>
                                <InputLabel>Store</InputLabel>
                                <Select
                                    value={selectedStore}
                                    label="Store"
                                    onChange={(e) => handleStoreChange(e.target.value)}
                                    disabled={loading}
                                >
                                    {stores.map((store) => (
                                        <MenuItem key={store.store_name} value={store.store_name}>
                                            <Box>
                                                <Typography variant="body1">
                                                    {store.store_name}
                                                </Typography>
                                                <Typography variant="caption" color="text.secondary">
                                                    {store.location}, {store.city} • {store.total_walls} walls
                                                </Typography>
                                            </Box>
                                        </MenuItem>
                                    ))}
                                </Select>
                            </FormControl>

                            {loading && (
                                <Box sx={{ display: 'flex', justifyContent: 'center', p: 2 }}>
                                    <CircularProgress />
                                </Box>
                            )}
                        </CardContent>
                    </Card>
                </Grid>

                {/* LOB Selection */}
                <Grid item xs={12} md={6}>
                    <Card>
                        <CardContent>
                            <Typography variant="h6" gutterBottom>
                                Select LOBs to Optimize
                            </Typography>

                            <FormGroup>
                                {['Apple Panel', 'TPA Panel', 'Mixed Panel'].map((lob) => (
                                    <FormControlLabel
                                        key={lob}
                                        control={
                                            <Checkbox
                                                checked={selectedLobs.includes(lob)}
                                                onChange={() => handleLobToggle(lob)}
                                                color={getLobColor(lob) as any}
                                            />
                                        }
                                        label={
                                            <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                                                <Chip 
                                                    label={lob} 
                                                    size="small" 
                                                    color={getLobColor(lob) as any}
                                                    variant="outlined"
                                                />
                                                {storeWalls && storeWalls.summary[lob] && (
                                                    <Typography variant="caption" color="text.secondary">
                                                        {storeWalls.summary[lob].wall_count} walls, {storeWalls.summary[lob].total_facings} facings
                                                    </Typography>
                                                )}
                                            </Box>
                                        }
                                    />
                                ))}
                            </FormGroup>

                            <Button
                                variant="contained"
                                onClick={startOptimization}
                                disabled={!selectedStore || selectedLobs.length === 0 || loading}
                                startIcon={<PlayArrow />}
                                sx={{ mt: 2 }}
                                fullWidth
                            >
                                Start Store Optimization
                            </Button>
                        </CardContent>
                    </Card>
                </Grid>

                {/* Store Wall Details */}
                {storeWalls && (
                    <Grid item xs={12}>
                        <Card>
                            <CardContent>
                                <Typography variant="h6" gutterBottom sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                                    <ViewModule />
                                    Store Layout: {storeWalls.store_name}
                                </Typography>

                                <Box sx={{ mb: 2 }}>
                                    <Typography variant="body2" color="text.secondary">
                                        Total: {storeWalls.total_walls} walls, {storeWalls.total_facings} facings
                                    </Typography>
                                </Box>

                                {Object.entries(storeWalls.lob_groups).map(([lob, walls]) => (
                                    walls.length > 0 && (
                                        <Accordion key={lob} defaultExpanded>
                                            <AccordionSummary expandIcon={<ExpandMore />}>
                                                <Box sx={{ display: 'flex', alignItems: 'center', gap: 2, width: '100%' }}>
                                                    <Chip 
                                                        label={lob} 
                                                        color={getLobColor(lob) as any}
                                                        size="small"
                                                    />
                                                    <Typography variant="body2" color="text.secondary">
                                                        {walls.length} walls • {storeWalls.summary[lob]?.total_facings || 0} facings
                                                    </Typography>
                                                </Box>
                                            </AccordionSummary>
                                            <AccordionDetails>
                                                <TableContainer component={Paper} variant="outlined">
                                                    <Table size="small">
                                                        <TableHead>
                                                            <TableRow>
                                                                <TableCell>Wall ID</TableCell>
                                                                <TableCell>Panel</TableCell>
                                                                <TableCell>Brand</TableCell>
                                                                <TableCell>Product</TableCell>
                                                                <TableCell align="right">Shelves</TableCell>
                                                                <TableCell align="right">Pegs</TableCell>
                                                                <TableCell align="right">Total Facings</TableCell>
                                                            </TableRow>
                                                        </TableHead>
                                                        <TableBody>
                                                            {walls.map((wall) => (
                                                                <TableRow key={wall.wall_id}>
                                                                    <TableCell>{wall.wall_id}</TableCell>
                                                                    <TableCell>{wall.panel_name}</TableCell>
                                                                    <TableCell>{wall.brand}</TableCell>
                                                                    <TableCell>
                                                                        <Typography variant="body2" noWrap>
                                                                            {wall.product}
                                                                        </Typography>
                                                                    </TableCell>
                                                                    <TableCell align="right">
                                                                        {wall.shelf_info.shelf_count > 0 && (
                                                                            <Typography variant="caption">
                                                                                {wall.shelf_info.shelf_count} × {wall.shelf_info.per_shelf}
                                                                            </Typography>
                                                                        )}
                                                                    </TableCell>
                                                                    <TableCell align="right">
                                                                        {wall.peg_info.peg_count > 0 && (
                                                                            <Typography variant="caption">
                                                                                {wall.peg_info.peg_count} × {wall.peg_info.per_peg}
                                                                            </Typography>
                                                                        )}
                                                                    </TableCell>
                                                                    <TableCell align="right">
                                                                        <Chip 
                                                                            label={wall.total_facings} 
                                                                            size="small" 
                                                                            variant="outlined"
                                                                        />
                                                                    </TableCell>
                                                                </TableRow>
                                                            ))}
                                                        </TableBody>
                                                    </Table>
                                                </TableContainer>
                                            </AccordionDetails>
                                        </Accordion>
                                    )
                                ))}
                            </CardContent>
                        </Card>
                    </Grid>
                )}
            </Grid>

            {/* Progress Tracker */}
            {progressOpen && currentJobId && (
                <ProgressTracker
                    jobId={currentJobId}
                    jobType="store_optimization"
                    open={progressOpen}
                    onClose={handleProgressClose}
                    onComplete={handleJobComplete}
                />
            )}

            {/* Results Viewer */}
            {resultsOpen && completedJobId && (
                <ResultsViewer
                    jobId={completedJobId}
                    open={resultsOpen}
                    onClose={handleResultsClose}
                />
            )}
        </Box>
    );
};

export default StoreOptimization;
